mapper.select:
SELECT r.reception_id, r.reception_no, r.patient_id, r.visit_type, r.department_id, r.doctor_id, r.reservation_id, r.scheduled_at, r.arrived_at, r.status, r.note, r.is_active, r.created_at, r.updated_at, e.triage_level, e.chief_complaint, e.vital_temp, e.vital_bp_systolic, e.vital_bp_diastolic, e.vital_hr, e.vital_rr, e.vital_spo2, e.arrival_mode, e.triage_note FROM reception r JOIN reception_emergency e ON r.reception_id = e.reception_id
r.visit_type = 'EMERGENCY'
AND r.patient_id = #{searchValue}
AND r.status = #{searchValue}
AND e.triage_level = #{searchValue}
ORDER BY e.triage_level ASC, r.created_at ASC
